-- Create database quickkart first, then run this schema.
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'Customer',department VARCHAR(80) DEFAULT 'Operations',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(80) NOT NULL,price NUMERIC(10,2) NOT NULL,stock INTEGER DEFAULT 0,status VARCHAR(30) DEFAULT 'Available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,customer_id INTEGER REFERENCES users(id),total_amount NUMERIC(10,2) NOT NULL,status VARCHAR(40) DEFAULT 'Preparing',payment_status VARCHAR(30) DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id SERIAL PRIMARY KEY,order_id INTEGER REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL,unit_price NUMERIC(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS offers(id SERIAL PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,discount_percent NUMERIC(5,2),active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
